void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //fix uv from FabriceNeyret2
    vec2 uv = ( fragCoord -.5* iResolution.xy ) / iResolution.x;
    //Default
    //vec2 uv = fragCoord.xy / iResolution.xy * vec2(1,1) + vec2(-0.5,-0.5);
    uv *= 0.5;

    V(uv,iTime,24.0,Out,Cells);

    vec3 d = vec3(PP(iTime * 0.0001,0.001) * 14.0 / Out);
    fragColor = vec4(d,1.0);
}

float Out = 0.0;
float Cells = 0.0;

vec2 N(vec2 UV, float offset)
{
    mat2 m = mat2(15.27, 47.63, 99.41, 89.98);
    UV = fract(sin(UV * m) * 46839.32);
    return vec2(sin(UV.y*+offset)*0.5+0.5, cos(UV.x*offset)*0.5+0.5);
}

void V(vec2 UV, float AngleOffset, float CellDensity, out float Out, out float Cells)
{
    vec2 g = floor(UV * CellDensity);
    vec2 f = fract(UV * CellDensity);
    float t = 8.0;
    vec3 res = vec3(8.0, 0.0, 0.0);

    for(int y=-1; y<=1; y++)
    {
        for(int x=-1; x<=1; x++)
        {
            vec2 lattice = vec2(x,y);
            vec2 offset = N(lattice + g, AngleOffset);
            float d = distance(lattice + offset, f);
            if(d < res.x)
            {
                res = vec3(d, offset.x, offset.y);
                Out = res.x;
                Cells = res.y;
            }
        }
    }
}

float PP(float t, float l)
{
    t = clamp(t - floor(t / l) * l,0.0,l) * 2.0;
    return l - abs(t - l);
}
